  ('reza-bazar', 'রেয়াজউদ্দিন বাজার', 'চট্টগ্রাম'),
  ('kazir-bazar', 'কাজীর বাজার', 'সিলেট'),
  ('rajshahi-bazar', 'সাহেব বাজার', 'রাজশাহী')
) as v(slug, name_bn, city) join districts d on d.name_bn = v.city
on conflict (slug) do nothing;

